'use strict';
const nutritionFaces=new Map(),nutritionColors={snow:{name:'Neve',color:'#ffffff'},rose:{name:'Rosa',color:'#fff0f5'},mint:{name:'Verde',color:'#edf8f0'},blue:{name:'Azul',color:'#edf5fc'},lavender:{name:'Lavanda',color:'#f3effb'},peach:{name:'Pêssego',color:'#fff3e9'}};
function nutritionFaceIndex(meal){const index=nutritionFaces.get(meal.id)||0;return index<1+(meal.variations?.length||0)?index:0}
function nutritionFace(meal){return [meal,...(meal.variations||[])][nutritionFaceIndex(meal)]}
function nutritionMealCard(meal,editor){const face=nutritionFace(meal),index=nutritionFaceIndex(meal),count=1+(meal.variations?.length||0),color=nutritionColors[face.color||'snow']||nutritionColors.snow;return `<article class="nutri-meal nutri-flip-card" data-mealcard="${esc(meal.id)}" style="--meal-color:${color.color}"><div class="nutri-meal-heading"><span class="nutri-meal-emoji">${esc(meal.emoji)}</span><div><h3>${esc(meal.name)}</h3><span class="nutri-time">${esc(meal.time)}</span></div>${editor?`<button class="nutri-icon-button" data-nutrimeal="${esc(meal.id)}" aria-label="Editar ${esc(meal.name)}">${icon('pencil')}</button>`:''}</div><div class="nutri-face-label">${index===0?'Opção principal':'Substituição '+index}${count>1?` · ${index+1}/${count}`:''}</div><ul class="nutri-foods">${face.foods.map(food=>`<li><span class="nutri-food-dot"></span>${esc(food)}</li>`).join('')}</ul>${face.note?`<p class="nutri-meal-note">${esc(face.note)}</p>`:''}<footer class="nutri-macros"><span><b>${nutritionNumber(face.kcal)}</b> kcal</span><span><b>${nutritionNumber(face.protein)} g</b> proteína</span><span><b>${nutritionNumber(face.carbs)} g</b> carboidratos</span><span><b>${nutritionNumber(face.fat)} g</b> lipídios</span></footer>${count>1||editor?`<div class="nutri-variation-actions">${count>1?`<button data-nutriflip="${esc(meal.id)}" aria-label="Mostrar próxima variação de ${esc(meal.name)}"><span aria-hidden="true">↻</span> Variação <small>${index+1}/${count}</small></button>`:''}${editor?`<button class="ghost" data-nutriaddvariation="${esc(meal.id)}">＋ Substituição</button>`:''}</div>`:''}</article>`}
function nutritionFlip(id){const meal=nutritionCurrent()?.meals.find(m=>m.id===id),card=document.querySelector(`[data-mealcard="${CSS.escape(id)}"]`);if(!meal||!card||!meal.variations?.length||card.classList.contains('nutri-turn-out'))return;const next=()=>{if(page!=='nutrition'||!nutritionCurrent()?.meals.some(m=>m.id===id))return;nutritionFaces.set(id,(nutritionFaceIndex(meal)+1)%(1+meal.variations.length));render();const newCard=document.querySelector(`[data-mealcard="${CSS.escape(id)}"]`);newCard?.classList.add('nutri-turn-in');newCard?.querySelector('[data-nutriflip]')?.focus({preventScroll:true})};if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)next();else{card.classList.add('nutri-turn-out');setTimeout(next,170)}}
function nutritionColorPicker(value){return `<fieldset class="nutri-color-picker"><legend>Cor do card</legend>${Object.entries(nutritionColors).map(([key,c])=>`<label title="${c.name}"><input type="radio" name="mealColor" value="${key}" ${(value||'snow')===key?'checked':''}><span style="background:${c.color}"></span>${c.name}</label>`).join('')}</fieldset>`}
function nutritionDeleteVariation(mealId,index,planId){if(!nutritionEditing()){nutritionRequire(()=>nutritionDeleteVariation(mealId,index,planId));return}modal(`<h2>Excluir substituição?</h2><p>A opção principal e as demais substituições serão mantidas.</p><div class="modal-actions"><button id="nutritioncanceldelete">Cancelar</button><button id="nutritionconfirmdelete" class="nutri-danger">Excluir</button></div>`);$('#nutritioncanceldelete').onclick=()=>nutritionMealForm(mealId,planId,index);$('#nutritionconfirmdelete').onclick=()=>{if(!nutritionEditing()){close();nutritionRequire(()=>nutritionDeleteVariation(mealId,index,planId));return}const data=structuredClone(nutritionData()),meal=data.plans.find(p=>p.id===planId)?.meals.find(m=>m.id===mealId);if(meal){meal.variations.splice(index-1,1);nutritionFaces.set(mealId,0);nutritionCommit(data)}}}
function bindNutritionVariants(){document.querySelectorAll('[data-nutriflip]').forEach(b=>b.onclick=()=>nutritionFlip(b.dataset.nutriflip));document.querySelectorAll('[data-nutriaddvariation]').forEach(b=>b.onclick=()=>{const meal=nutritionCurrent().meals.find(m=>m.id===b.dataset.nutriaddvariation);nutritionMealForm(meal.id,nutritionCurrent().id,1+(meal.variations?.length||0))});document.querySelectorAll('[data-nutrimeal]').forEach(b=>b.onclick=()=>{const meal=nutritionCurrent().meals.find(m=>m.id===b.dataset.nutrimeal);nutritionMealForm(meal.id,nutritionCurrent().id,nutritionFaceIndex(meal))})}
